//! Recall + latency harness.
//!
//! A speedup number without a recall number says nothing about an approximate
//! index — it is always possible to be fast by being wrong. This reports both,
//! and takes two precautions the earlier benchmark skipped:
//!
//!   * every path is warmed before timing, so the first method measured does not
//!     pay the page-cache cost that the second then benefits from;
//!   * queries are perturbations of many different stored vectors, not one
//!     vector generated by the same formula as row 0.

use std::hint::black_box;
use std::time::Instant;

use harness_memory::hnsw::{HnswConfig, HnswIndex};
use harness_memory::quant::{F32Query, QuantizedVector};
use harness_memory::simd;
use harness_memory::store::{SegmentPaths, SegmentReader, SegmentWriter};

const DIM: usize = 384;
const N: usize = 20_000;
const QUERIES: usize = 200;
const K: usize = 10;

fn percentile(sorted_micros: &[f64], p: f64) -> f64 {
    if sorted_micros.is_empty() {
        return 0.0;
    }
    let idx = ((sorted_micros.len() - 1) as f64 * p).round() as usize;
    sorted_micros[idx]
}

/// Deterministic xorshift so both modes are reproducible.
fn rand_unit(seed: u64) -> Vec<f32> {
    let mut x = seed.wrapping_mul(0x9E3779B97F4A7C15) | 1;
    (0..DIM)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            ((x >> 40) as f32 / 8_388_608.0) - 1.0
        })
        .collect()
}

fn synth(i: usize) -> Vec<f32> {
    if std::env::var("HARD").is_ok() {
        // Unstructured high-dimensional noise: the adversarial case for any
        // graph index, and the honest lower bound on recall.
        return rand_unit(i as u64 + 1);
    }
    // 40 clusters with per-item jitter, plus two outlier dimensions to exercise
    // the clipping path the way real embeddings do.
    let cluster = (i % 40) as f32;
    let mut v: Vec<f32> = (0..DIM)
        .map(|d| {
            (d as f32 * 0.05 + cluster * 2.7).sin() * 0.4
                + (i as f32 * 0.0007 + d as f32 * 0.31).cos() * 0.12
        })
        .collect();
    v[13] *= 8.0;
    v[200] *= 6.0;
    v
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let dir = std::env::temp_dir().join(format!("hm-bench-{}", std::process::id()));
    std::fs::create_dir_all(&dir)?;
    let paths = SegmentPaths::in_dir(&dir);

    println!(
        "kernel: {}   dim: {}   rows: {}",
        simd::active_kernel_name(),
        DIM,
        N
    );

    // ---------------------------------------------------------------- build
    let t = Instant::now();
    let mut sources = Vec::with_capacity(N);
    {
        let mut w = SegmentWriter::open(&paths, DIM)?;
        for i in 0..N {
            let v = synth(i);
            w.append(&QuantizedVector::quantize_clipped(&v, 0.995), b"{}")?;
            sources.push(v);
        }
        w.commit_durable()?;
    }
    let write_time = t.elapsed();

    let reader = SegmentReader::open(paths.clone())?;
    let snap = reader.snapshot();

    let vec_bytes = std::fs::metadata(&paths.vectors)?.len();
    println!(
        "\nwrite:  {:?}  ({:.1} MB on disk, {:.0} B/row vs {} B/row as f32)",
        write_time,
        vec_bytes as f64 / 1_048_576.0,
        vec_bytes as f64 / N as f64,
        DIM * 4
    );

    let t = Instant::now();
    let mut cfg = HnswConfig::default();
    if let Ok(v) = std::env::var("EF") {
        cfg.ef_search = v.parse().unwrap_or(cfg.ef_search);
    }
    if let Ok(v) = std::env::var("EFC") {
        cfg.ef_construction = v.parse().unwrap_or(cfg.ef_construction);
    }
    let mut index = HnswIndex::new_seeded(cfg, snap.clone(), 1234);
    for row in 0..N as u32 {
        index.insert(row)?;
    }
    println!("build:  {:?}  ({} nodes)", t.elapsed(), index.len());

    // -------------------------------------------------------------- queries
    let queries: Vec<F32Query> = (0..QUERIES)
        .map(|q| {
            let src = &sources[(q * 97 + 11) % N];
            F32Query::new(
                src.iter()
                    .enumerate()
                    .map(|(d, x)| x + (d as f32 * 0.02 + q as f32 * 1.7).sin() * 0.08)
                    .collect::<Vec<f32>>(),
            )
        })
        .collect();

    // Warm both paths before timing either. Without this the first method
    // measured absorbs all the page faults and the second looks artificially
    // fast — which is how a linear-vs-HNSW comparison gets inflated.
    for q in queries.iter().take(5) {
        black_box(snap.brute_force(q, K));
        black_box(index.search(q, K)?);
    }

    let mut truth = Vec::with_capacity(QUERIES);
    let mut brute_us = Vec::with_capacity(QUERIES);
    for q in &queries {
        let t = Instant::now();
        let r = snap.brute_force(q, K);
        brute_us.push(t.elapsed().as_secs_f64() * 1e6);
        truth.push(r.into_iter().map(|(row, _)| row).collect::<Vec<u32>>());
    }

    let mut hnsw_us = Vec::with_capacity(QUERIES);
    let mut hits = 0usize;
    for (q, gold) in queries.iter().zip(truth.iter()) {
        let t = Instant::now();
        let got = index.search(q, K)?;
        hnsw_us.push(t.elapsed().as_secs_f64() * 1e6);
        hits += got.iter().filter(|(row, _)| gold.contains(row)).count();
    }

    brute_us.sort_by(|a, b| a.partial_cmp(b).unwrap());
    hnsw_us.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let recall = hits as f64 / (QUERIES * K) as f64;
    println!("\n--- retrieval over {} queries ---", QUERIES);
    println!(
        "exhaustive   p50 {:>8.1} us   p99 {:>8.1} us",
        percentile(&brute_us, 0.50),
        percentile(&brute_us, 0.99)
    );
    println!(
        "hnsw         p50 {:>8.1} us   p99 {:>8.1} us   recall@{} {:.3}",
        percentile(&hnsw_us, 0.50),
        percentile(&hnsw_us, 0.99),
        K,
        recall
    );
    println!(
        "speedup at p50: {:.1}x  (only meaningful alongside the recall figure)",
        percentile(&brute_us, 0.50) / percentile(&hnsw_us, 0.50).max(1e-9)
    );

    // ------------------------------------------------------------ dot kernel
    // black_box on both inputs and the result, otherwise LLVM hoists the whole
    // loop-invariant computation and the "speedup" measures dead-code removal.
    let a = QuantizedVector::quantize(&sources[0]);
    let b = QuantizedVector::quantize(&sources[1]);
    let iters = 2_000_000usize;

    let t = Instant::now();
    let mut acc = 0i64;
    for _ in 0..iters {
        acc += simd::dot_i8_scalar(black_box(&a.bytes), black_box(&b.bytes)) as i64;
    }
    let scalar_time = t.elapsed();
    black_box(acc);

    let kernel = simd::dot_i8_kernel();
    let t = Instant::now();
    let mut acc2 = 0i64;
    for _ in 0..iters {
        acc2 += kernel(black_box(&a.bytes), black_box(&b.bytes)) as i64;
    }
    let simd_time = t.elapsed();
    black_box(acc2);

    assert_eq!(acc, acc2, "scalar and SIMD kernels disagree");
    println!(
        "\n--- dot product ({} dims, {} iterations) ---\nscalar {:?}   {} {:?}   {:.2}x",
        DIM,
        iters,
        scalar_time,
        simd::active_kernel_name(),
        simd_time,
        scalar_time.as_secs_f64() / simd_time.as_secs_f64()
    );

    std::fs::remove_dir_all(&dir).ok();
    Ok(())
}
